@media (forced-colors: active) {
  .option { border-color: CanvasText; }
  .option:has(input:checked) { border-color: Highlight; }
  input[type="radio"]:checked::before { background: Highlight; }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }
}
