  --bg: #0e1116;
  --surface: #161b22;
  --surface-2: #1f262f;
  --border: #30363d;
  --text: #e6edf3;
  --text-muted: #9aa4b2;
  --accent: #6ea8ff;
  --accent-strong: #1158c7;
  --danger: #ff7b72;
  --focus: #ffd166;
  --success: #3fb950;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--focus);
  color: #111;
  padding: 0.5rem 0.75rem;
  border-radius: 4px;
  font-weight: 600;
  z-index: 100;
}
.skip-link:focus {
  left: 1rem;
  top: 1rem;
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

main {
  max-width: 560px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

h1 {
  font-size: 1.75rem;
  margin: 0 0 0.5rem;
  letter-spacing: -0.01em;
}

.intro {
  color: var(--text-muted);
  margin: 0 0 1.75rem;
}

form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.form-field {
  margin-bottom: 1.5rem;
}

fieldset {
  border: none;
  margin: 0;
  padding: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  padding: 0;
  margin-bottom: 0.25rem;
}

.req {
  color: var(--danger);
  margin-left: 0.15rem;
}

.help {
  margin: 0 0 1rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.options {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem 0.9rem;
  transition: border-color 120ms ease, background-color 120ms ease;
}

.option:hover {
  border-color: #4a5460;
}

.option:has(input:checked) {
  border-color: var(--accent-strong);
  background: #1a2433;
}

.option:has(input:focus-visible) {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  border: 2px solid #6e7781;
  border-radius: 50%;
  margin: 0;
  display: inline-grid;
  place-content: center;
  background: transparent;
  cursor: pointer;
  flex-shrink: 0;
}

input[type="radio"]::before {
  content: "";
  width: 0.6rem;
  height: 0.6rem;
  border-radius: 50%;
  background: var(--accent);
  transform: scale(0);
  transition: transform 120ms ease-in-out;
}

input[type="radio"]:checked {
  border-color: var(--accent-strong);
}

input[type="radio"]:checked::before {
  transform: scale(1);
}

input[type="radio"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

label {
  cursor: pointer;
  flex: 1;
  user-select: none;
}

.submit-btn {
  display: inline-block;
  background: var(--accent-strong);
  color: #fff;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.7rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 120ms ease, transform 80ms ease;
  min-height: 44px;
}

.submit-btn:hover { background: #4493f8; }
.submit-btn:active { transform: translateY(1px); }
.submit-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.status {
  margin: 1rem 0 0;
  min-height: 1.25rem;
  font-size: 0.95rem;
}
.status.success { color: var(--success); }
.status.error { color: var(--danger); }

@media (prefers-reduced-motion: reduce) {
  input[type="radio"]::before,
  .submit-btn,
  .option {
    transition: none;
  }
}

@media (forced-colors: active) {
  .option { border-color: CanvasText; }
  .option:has(input:checked) { border-color: Highlight; }
  input[type="radio"]:checked::before { background: Highlight; }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border-color: ButtonText;
  }
}
